  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEFA", 50);
  brush.fillBleed(0.7);
  brush.fillTexture(1, 0);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  // Green hills
  brush.fill("#336600", 70);
  brush.fillBleed(0.5);
  brush.fillTexture(0.5, 0);
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(400, 250);
  brush.vertex(0, 250);
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700", 100);
  brush.fillBleed(0.8);
  brush.fillTexture(0.8, 0);
  brush.beginShape();
  brush.vertex(0, 100);
  brush.vertex(400, 100);
  brush.vertex(200, 150);
  brush.endShape(true);
}

