  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEFA", 100);
  brush.fillBleed(0.3);
  brush.fillTexture(1, 0);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  // Green hills
  brush.fill("#006400", 80);
  brush.fillBleed(0.2);
  brush.fillTexture(0.5, 0);
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(400, 250);
  brush.vertex(0, 250);
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700", 100);
  brush.fillBleed(0.4);
  brush.fillTexture(0.8, 0);
  brush.beginShape();
  brush.vertex(200, 150);
  brush.vertex(250, 120);
  brush.vertex(200, 100);
  brush.vertex(150, 120);
  brush.vertex(100, 150);
  brush.endShape(true);
}

