  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEFA", 100);
  brush.fillBleed(0.5);
  brush.fillTexture(0.5, 0);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  // Green hills
  brush.fill("#468243", 100);
  brush.fillBleed(0.3);
  brush.fillTexture(0.3, 0);
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(400, 250);
  brush.vertex(0, 250);
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700", 100);
  brush.fillBleed(0.8);
  brush.fillTexture(0.8, 0);
  brush.beginShape();
  brush.vertex(200, 200);
  brush.vertex(180, 180);
  brush.vertex(220, 180);
  brush.vertex(200, 220);
  brush.endShape(true);
}

